    private createCommitMessage() {
        const messages = [...this.pendingMessagesByPath.values()].flat()
        const distinctMessages = [...new Set(messages)]
        if (distinctMessages.length === 1) return distinctMessages[0]

        const body = distinctMessages.map((message) => `- ${message}`).join('\n')

        return `Update ${this.pendingChanges.size} files\n\n${body}`
    }

    private createFlushCallback() {
        return () => {
            void this.flush().catch((error: unknown) => {
                this.dispatchEvent(new CustomEvent(COMMIT_BATCHER_FLUSH_FAILED_EVENT, { detail: error }))
            })
        }
    }

    private clearScheduledDelay() {
        if (this.scheduledDelayId === null) return

        window.clearTimeout(this.scheduledDelayId)
        this.scheduledDelayId = null
    }
}

import type { ActionDefinition, RawActionDefinition } from '../data/action_types'
import type { Card } from '../data/data_types'

export type OpenDocumentObject = Card | ActionDefinition
export interface CardBodyDraft {
    content: string
}
export type OpenDocumentDraft = CardBodyDraft | RawActionDefinition
export type OpenDocumentOrigin = object | string | null

export interface OpenDocumentSaveReference {
    readonly document: OpenDocument
    acknowledge(): void
}

export interface OpenDocumentChangedDetail {
    document: OpenDocument
    origin: OpenDocumentOrigin
    type: 'dirty' | 'draft' | 'renewed' | 'saved'
}

interface OpenDocumentBase<TObject extends OpenDocumentObject, TDraft extends OpenDocumentDraft> extends EventTarget {
    readonly dirty: boolean
    readonly kind: 'action' | 'card'
    readonly path: string
    createSaveReference(): OpenDocumentSaveReference
    getDraft(): TDraft
    getObject(): TObject
    replaceDraft(draft: TDraft): void
    updateDraft(draft: TDraft, origin?: OpenDocumentOrigin): void
}

export interface ActionOpenDocument extends OpenDocumentBase<ActionDefinition, RawActionDefinition> {
    readonly kind: 'action'
}

export interface CardOpenDocument extends OpenDocumentBase<Card, CardBodyDraft> {
    readonly kind: 'card'
}

export type OpenDocument = ActionOpenDocument | CardOpenDocument

import type { ActionDefinition } from '../data/action_types'
import type { Card, ProjectReference, ProjectSnapshot } from '../data/data_types'
import { ACTIONS_CHANGED_EVENT, ACTION_DRAFT_CHANGED_EVENT } from './actions/action_service_events'
import { CARD_CHANGED_EVENT } from './data/card_events'
import type { CardChangedEventDetail } from './data/data_service'
import { register } from './service_injector'
import { ManagedOpenDocument } from './managed_open_document'
import type {
    CardOpenDocument,
    OpenDocument,
    CardBodyDraft,
    OpenDocumentChangedDetail,
    OpenDocumentDraft,
    OpenDocumentObject,
} from './open_document'

export type {
    ActionOpenDocument,
    CardOpenDocument,
    OpenDocument,
    OpenDocumentChangedDetail,
    OpenDocumentDraft,
    OpenDocumentObject,
    OpenDocumentOrigin,
    OpenDocumentSaveReference,
} from './open_document'

export interface OpenDocumentEventDetail {
    document: OpenDocument
}

export interface OpenFilesSnapshot {
    activeDocument: OpenDocument | null
    documents: readonly OpenDocument[]
}

interface OpenFilesDependencies {
    actionService: EventTarget & Pick<import('./actions/action_service').ActionService, 'getActions' | 'draftStore'>
    dataService: EventTarget & Pick<import('./data/data_service').DataService, 'getState'>
}

const EMPTY_SNAPSHOT: OpenFilesSnapshot = { activeDocument: null, documents: [] }

function isCard(object: OpenDocumentObject): object is Card {
    return 'header' in object
}

function isCardDraft(draft: OpenDocumentDraft): draft is CardBodyDraft {
    return 'content' in draft
}

/** Cards are identified by their stable internal ID; regular markdown files have none and use their path. */
function documentIdentity(object: OpenDocumentObject) {
    if (!isCard(object)) return object.id

    return object.header.internalId ?? object.path
}

function projectKey(project: ProjectReference | null) {
